INSERT INTO ai_prep_question_bank (category, subject, concept, difficulty, scope, estimated_time_seconds, question_text, ground_truth, is_active)
VALUES
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'Prior to your current role, what hands-on experience did you have building or experimenting with agentic AI systems and side projects?', '{"version": 1, "rubric_version": "142.2", "topic": "Python & Data Manipulation", "subcategory": "AI-Assisted Software Engineering", "question_type": "TECHNICAL_CONCEPT", "question_intent": "EXPERIENCE", "reference_answer": "AI coding assistants and companion agents (e.g. Cursor, Copilot, automated PR review agents) accelerate development through context-aware autocompletion, boilerplate generation, AST-aware code navigation, and test generation. To prevent regressions, outputs must undergo strict deterministic verification: syntax linting, static analysis, unit test execution, and human code review. Measurable impact is tracked through reduced PR review turnaround time, test coverage improvements, and developer velocity while mitigating risks around hallucinated APIs and security vulnerabilities.", "evidence_policy": {"acceptable_evidence_is_non_exhaustive": true, "semantic_equivalence_allowed": true, "evaluator_guidance": "acceptable_evidence lists representative examples of valid technical evidence, not mandatory keywords. Any technically equivalent demonstration or alternative valid architecture must receive full credit.", "criteria_weight_policy": "All criteria weights sum to 100 points. Criteria marked required: true represent non-negotiable core competency dimensions that require demonstrative evidence to pass the question. Criteria marked required: false represent architectural depth or operational nuance that additively contribute to the total score."}, "evaluation": {"criteria": [{"name": "Relevant Domain Experience", "weight": 35, "description": "Articulates concrete hands-on background and project history in the relevant domain."}, {"name": "Technical Depth & Contributions", "weight": 35, "description": "Explains specific tools, frameworks, and personal contributions to past projects."}, {"name": "Growth & Continuous Learning", "weight": 30, "description": "Demonstrates active self-directed learning, side projects, or career progression."}], "critical_failures": ["Provides superficial or generalized responses lacking concrete hands-on implementation details.", "Fails to demonstrate relevant background or hands-on experimentation in the topic."]}, "question_code": "TECH-AGT-001"}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How do you approach hands-on implementation and technical execution when building a multi-agent system?', '{"version": 1, "rubric_version": "142.2", "topic": "Agentic AI & Multi-Agent Systems", "subcategory": "Multi-Agent System Architecture", "question_type": "TECHNICAL_CONCEPT", "question_intent": "ARCHITECTURE_EXPLANATION", "reference_answer": "The system employs a hierarchical supervisor-worker multi-agent architecture to manage complex domain tasks. An Orchestrator/Supervisor agent maintains global workflow state, performs intent classification, and delegates domain sub-tasks to specialized domain agents (e.g., Knowledge Agent, Transaction Agent, Policy Agent). Agents communicate via structured schemas over a shared state graph. Tools are decoupled from reasoning, exposed as typed functions with strict parameter validation. Resilience is ensured through self-reflection loops for transient errors, recursion depth limits to prevent infinite execution cycles, and escalation paths to human operators.", "evidence_policy": {"acceptable_evidence_is_non_exhaustive": true, "semantic_equivalence_allowed": true, "evaluator_guidance": "acceptable_evidence lists representative examples of valid technical evidence, not mandatory keywords. Any technically equivalent demonstration or alternative valid architecture must receive full credit.", "criteria_weight_policy": "All criteria weights sum to 100 points. Criteria marked required: true represent non-negotiable core competency dimensions that require demonstrative evidence to pass the question. Criteria marked required: false represent architectural depth or operational nuance that additively contribute to the total score."}, "evaluation": {"criteria": [{"id": "C1", "description": "Multi-Agent Roles & Architecture: Defines clear agent roles, responsibilities, and separation of concerns across domain boundaries", "weight": 35, "required": true, "acceptable_evidence": ["Supervisor / Orchestrator coordination pattern", "Specialized domain workers with dedicated tools", "Decoupling reasoning from execution"]}, {"id": "C2", "description": "Coordination, State & Communication: Explains how state and message payloads flow between supervisor and domain agents", "weight": 35, "required": true, "acceptable_evidence": ["Shared state dictionary and context passing", "Structured input/output contracts between agents", "Parallel vs sequential sub-task execution"]}, {"id": "C3", "description": "Validation, Fallback & Escalation: Covers error handling, infinite loop prevention, guardrail validation, and human handoff", "weight": 30, "required": false, "acceptable_evidence": ["Step/depth limits (max iterations)", "Output validation and reflection loops", "Graceful fallback and human escalation"]}], "critical_failures": ["Designs a monolithic prompt instead of specialized agent roles", "Lacks mechanisms to prevent infinite agent execution loops"]}, "question_code": "TECH-AGT-002"}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'Can you describe the architecture of your multi-agent system and the role of each agent?', '{"version": 1, "rubric_version": "142.2", "topic": "Agentic AI & Multi-Agent Systems", "subcategory": "Multi-Agent System Architecture", "question_type": "TECHNICAL_CONCEPT", "question_intent": "ARCHITECTURE_EXPLANATION", "reference_answer": "The system employs a hierarchical supervisor-worker multi-agent architecture to manage complex domain tasks. An Orchestrator/Supervisor agent maintains global workflow state, performs intent classification, and delegates domain sub-tasks to specialized domain agents (e.g., Knowledge Agent, Transaction Agent, Policy Agent). Agents communicate via structured schemas over a shared state graph. Tools are decoupled from reasoning, exposed as typed functions with strict parameter validation. Resilience is ensured through self-reflection loops for transient errors, recursion depth limits to prevent infinite execution cycles, and escalation paths to human operators.", "evidence_policy": {"acceptable_evidence_is_non_exhaustive": true, "semantic_equivalence_allowed": true, "evaluator_guidance": "acceptable_evidence lists representative examples of valid technical evidence, not mandatory keywords. Any technically equivalent demonstration or alternative valid architecture must receive full credit.", "criteria_weight_policy": "All criteria weights sum to 100 points. Criteria marked required: true represent non-negotiable core competency dimensions that require demonstrative evidence to pass the question. Criteria marked required: false represent architectural depth or operational nuance that additively contribute to the total score."}, "evaluation": {"criteria": [{"id": "C1", "description": "Multi-Agent Roles & Architecture: Defines clear agent roles, responsibilities, and separation of concerns across domain boundaries", "weight": 35, "required": true, "acceptable_evidence": ["Supervisor / Orchestrator coordination pattern", "Specialized domain workers with dedicated tools", "Decoupling reasoning from execution"]}, {"id": "C2", "description": "Coordination, State & Communication: Explains how state and message payloads flow between supervisor and domain agents", "weight": 35, "required": true, "acceptable_evidence": ["Shared state dictionary and context passing", "Structured input/output contracts between agents", "Parallel vs sequential sub-task execution"]}, {"id": "C3", "description": "Validation, Fallback & Escalation: Covers error handling, infinite loop prevention, guardrail validation, and human handoff", "weight": 30, "required": false, "acceptable_evidence": ["Step/depth limits (max iterations)", "Output validation and reflection loops", "Graceful fallback and human escalation"]}], "critical_failures": ["Designs a monolithic prompt instead of specialized agent roles", "Lacks mechanisms to prevent infinite agent execution loops"]}, "question_code": "TECH-AGT-003"}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 120, 'Can you describe the specific architectural components of the agentic system, including the purpose of the orchestrator agent, the roles of the specialized domain agents (client, billing, accounts, appointments), and the use of the supervisor pattern?', '{"version": 1, "rubric_version": "142.2", "topic": "Agentic AI & Multi-Agent Systems", "subcategory": "Multi-Agent System Architecture", "question_type": "TECHNICAL_CONCEPT", "question_intent": "ARCHITECTURE_EXPLANATION", "reference_answer": "The system employs a hierarchical supervisor-worker multi-agent architecture to manage complex domain tasks. An Orchestrator/Supervisor agent maintains global workflow state, performs intent classification, and delegates domain sub-tasks to specialized domain agents (e.g., Knowledge Agent, Transaction Agent, Policy Agent). Agents communicate via structured schemas over a shared state graph. Tools are decoupled from reasoning, exposed as typed functions with strict parameter validation. Resilience is ensured through self-reflection loops for transient errors, recursion depth limits to prevent infinite execution cycles, and escalation paths to human operators.", "evidence_policy": {"acceptable_evidence_is_non_exhaustive": true, "semantic_equivalence_allowed": true, "evaluator_guidance": "acceptable_evidence lists representative examples of valid technical evidence, not mandatory keywords. Any technically equivalent demonstration or alternative valid architecture must receive full credit.", "criteria_weight_policy": "All criteria weights sum to 100 points. Criteria marked required: true represent non-negotiable core competency dimensions that require demonstrative evidence to pass the question. Criteria marked required: false represent architectural depth or operational nuance that additively contribute to the total score."}, "evaluation": {"criteria": [{"id": "C1", "description": "Multi-Agent Roles & Architecture: Defines clear agent roles, responsibilities, and separation of concerns across domain boundaries", "weight": 35, "required": true, "acceptable_evidence": ["Supervisor / Orchestrator coordination pattern", "Specialized domain workers with dedicated tools", "Decoupling reasoning from execution"]}, {"id": "C2", "description": "Coordination, State & Communication: Explains how state and message payloads flow between supervisor and domain agents", "weight": 35, "required": true, "acceptable_evidence": ["Shared state dictionary and context passing", "Structured input/output contracts between agents", "Parallel vs sequential sub-task execution"]}, {"id": "C3", "description": "Validation, Fallback & Escalation: Covers error handling, infinite loop prevention, guardrail validation, and human handoff", "weight": 30, "required": false, "acceptable_evidence": ["Step/depth limits (max iterations)", "Output validation and reflection loops", "Graceful fallback and human escalation"]}], "critical_failures": ["Designs a monolithic prompt instead of specialized agent roles", "Lacks mechanisms to prevent infinite agent execution loops"]}, "question_code": "TECH-AGT-004"}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'Can you describe your experience building multi-agent systems, including task decomposition, execution flow, and fallback mechanisms?', '{"version": 1, "rubric_version": "142.2", "topic": "Agentic AI & Multi-Agent Systems", "subcategory": "Routing & Planning", "question_type": "TECHNICAL_CONCEPT", "question_intent": "CAREER_PROGRESSION_OWNERSHIP", "reference_answer": "Routing and planning govern how queries are classified, decomposed, and executed. The router performs intent classification using semantic embeddings, few-shot classifiers, or fast small LLMs with structured output schemas. Complex queries are decomposed by a planner agent into directed sub-tasks with dependency graphs. Ambiguous intents trigger interactive clarification turns rather than hallucinations, while unrecognized queries route to fallback domain agents or human escalation queues.", "evidence_policy": {"acceptable_evidence_is_non_exhaustive": true, "semantic_equivalence_allowed": true, "evaluator_guidance": "acceptable_evidence lists representative examples of valid technical evidence, not mandatory keywords. Any technically equivalent demonstration or alternative valid architecture must receive full credit.", "criteria_weight_policy": "All criteria weights sum to 100 points. Criteria marked required: true represent non-negotiable core competency dimensions that require demonstrative evidence to pass the question. Criteria marked required: false represent architectural depth or operational nuance that additively contribute to the total score."}, "evaluation": {"criteria": [{"name": "Role Scope & Ownership", "weight": 35, "description": "Describes clear responsibilities, architecture ownership, and system impact in recent roles."}, {"name": "Technical & Cross-functional Leadership", "weight": 35, "description": "Explains engineering decisions, collaboration with stakeholders, and technical leadership."}, {"name": "System Scale & Complexity", "weight": 30, "description": "Details scale, throughput, reliability requirements, or AI integration scope of systems owned."}], "critical_failures": ["Vague description of personal role without specific technical contributions or ownership.", "Unable to explain architectural decisions or system scope in previous work."]}, "question_code": "TECH-AGT-005"}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'Can you describe your experience deploying AI/ML systems on AWS, including the use of Bedrock, EKS, Docker, and CloudWatch for monitoring and orchestration?', '{"version": 1, "rubric_version": "142.2", "topic": "Cloud Architecture & Services", "subcategory": "Cloud & Deployment Architecture", "question_type": "TECHNICAL_CONCEPT", "question_intent": "CAREER_PROGRESSION_OWNERSHIP", "reference_answer": "Deploying AI agents on AWS pairs containerized microservices with managed model endpoints. Agent orchestrators run in Docker containers on Amazon EKS (or ECS Fargate) utilizing Horizontal Pod Autoscaling (HPA) and stateless worker designs. Models are accessed via Amazon Bedrock with PrivateLink VPC endpoints for compliance and IAM least-privilege access. State is persisted in ElastiCache Redis (session state) and RDS/Aurora (checkpointing), with CloudWatch and AWS X-Ray providing distributed tracing and metric alarms.", "evidence_policy": {"acceptable_evidence_is_non_exhaustive": true, "semantic_equivalence_allowed": true, "evaluator_guidance": "acceptable_evidence lists representative examples of valid technical evidence, not mandatory keywords. Any technically equivalent demonstration or alternative valid architecture must receive full credit.", "criteria_weight_policy": "All criteria weights sum to 100 points. Criteria marked required: true represent non-negotiable core competency dimensions that require demonstrative evidence to pass the question. Criteria marked required: false represent architectural depth or operational nuance that additively contribute to the total score."}, "evaluation": {"criteria": [{"name": "Role Scope & Ownership", "weight": 35, "description": "Describes clear responsibilities, architecture ownership, and system impact in recent roles."}, {"name": "Technical & Cross-functional Leadership", "weight": 35, "description": "Explains engineering decisions, collaboration with stakeholders, and technical leadership."}, {"name": "System Scale & Complexity", "weight": 30, "description": "Details scale, throughput, reliability requirements, or AI integration scope of systems owned."}], "critical_failures": ["Vague description of personal role without specific technical contributions or ownership.", "Unable to explain architectural decisions or system scope in previous work."]}, "question_code": "TECH-AGT-006"}', 1),
